<!-- Interactive Feedback Toast -->
<div class="fixed bottom-space-lg right-space-lg bg-primary text-on-primary px-space-md py-space-sm shadow-xl font-label-caps text-label-caps uppercase tracking-wider transform translate-y-24 opacity-0 transition-all duration-300 z-50 flex items-center gap-space-sm" id="toastNotification">
<span class="material-symbols-outlined text-[18px]">verified</span>
<span id="toastMessage">ITEM ADDED</span>
</div>
<script>
    function showNotification(msg) {
      const toast = document.getElementById('toastNotification');
      const toastMsg = document.getElementById('toastMessage');
      if (toast && toastMsg) {
        toastMsg.textContent = msg;
        toast.classList.remove('translate-y-24', 'opacity-0');
        toast.classList.add('translate-y-0', 'opacity-100');
        setTimeout(() => {
          toast.classList.add('translate-y-24', 'opacity-0');
          toast.classList.remove('translate-y-0', 'opacity-100');
        }, 3200);
      }
    }

    function filterCategory(cat) {
      const tabs = document.querySelectorAll('.filter-tab');
      const cards = document.querySelectorAll('.look-card');

      tabs.forEach(tab => {
        if (tab.getAttribute('data-filter') === cat) {
          tab.classList.remove('bg-surface-container', 'text-on-surface');
          tab.classList.add('bg-primary', 'text-on-primary');
        } else {
          tab.classList.add('bg-surface-container', 'text-on-surface');
          tab.classList.remove('bg-primary', 'text-on-primary');
        }
      });

      cards.forEach(card => {
        const itemCategories = card.getAttribute('data-category') || '';
        if (cat === 'all' || itemCategories.includes(cat)) {
          card.style.display = 'flex';
        } else {
          card.style.display = 'none';
        }
      });

      const gridElem = document.getElementById('lookbookGrid');
      if (gridElem) {
        gridElem.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }
    }

    document.addEventListener('DOMContentLoaded', () => {
      const tabs = document.querySelectorAll('.filter-tab');
      tabs.forEach(tab => {
        tab.addEventListener('click', () => {
          const filter = tab.getAttribute('data-filter');
          filterCategory(filter);
        });
      });

      const homeLink = document.createElement('a');
      homeLink.id = 'lookbook-home';
      homeLink.href = @json(route('home'));
      homeLink.textContent = 'HOME';
      homeLink.className = 'px-space-md py-space-xs bg-primary text-on-primary font-label-caps text-label-caps uppercase tracking-widest hover:bg-secondary transition-colors';
      document.querySelector('header > div > div:last-child')?.prepend(homeLink);

      const productSlugs = [
        'k-10-wide-pleat-trouser',
        'k-07-raw-cut-box-tee',
        'k-02-dropped-raglan-longline',
        'k-04-sculpted-oversized-hoodie',
        'k-05-structural-raglan-crew',
        'k-09-modular-field-cargo',
        'k-11-modular-chest-harness',
        'brutalist-monolith-cuff-ring-set'
      ];
      const csrf = document.querySelector('#lookbook-cart-token input[name="_token"]')?.value;
      document.querySelectorAll('#lookbookGrid .look-card').forEach((card, index) => {
        const imageFrame = card.querySelector('.relative');
        const image = card.querySelector('img');
        const name = card.querySelector('h3')?.textContent.trim();
        const price = card.querySelector('.font-price-lg')?.textContent.trim();
        if (!imageFrame || !image || !name || !price || !productSlugs[index]) return;

        imageFrame.classList.add('lookbook-image-link');
        imageFrame.setAttribute('role', 'link');
        imageFrame.setAttribute('tabindex', '0');
        const acquire = async () => {
          imageFrame.setAttribute('aria-busy', 'true');
          try {
            const response = await fetch(@json(route('cart.add')), {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
                'Accept': 'application/json',
                'X-CSRF-TOKEN': csrf
              },
              body: JSON.stringify({ slug: productSlugs[index], name, price, image: image.src })
            });
            const result = await response.json();
            if (!response.ok) throw new Error('Unable to add item');
            window.location.href = result.redirect;
          } catch (error) {
            imageFrame.removeAttribute('aria-busy');
            showNotification('Unable to add this look right now');
          }
        };
        imageFrame.addEventListener('click', acquire);
        imageFrame.addEventListener('keydown', (event) => {
          if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); acquire(); }
        });
      });
    });
  </script>
